"""Pricing rules."""


def line_total(price: float, qty: int) -> float:
    return round(price * qty, 2)

seedFiles.app/cart.py:
from app.pricing import line_total


def checkout(items: list[dict]) -> float:
    return round(sum(line_total(i["price"], i["qty"]) for i in items), 2)

