import pytest

from app.cart import checkout
from app.pricing import apply_discount

ITEMS = [{"price": 10.0, "qty": 2}, {"price": 5.0, "qty": 4}]


def test_checkout_without_code():
    assert checkout(ITEMS) == 40.0


def test_apply_discount_10():
    assert apply_discount(100.0, "SAVE10") == 90.0


def test_apply_discount_25():
    assert apply_discount(100.0, "SAVE25") == 75.0


def test_unknown_code_rejected():
    with pytest.raises(ValueError):
        apply_discount(100.0, "NOPE")


def test_checkout_with_code():
    assert checkout(ITEMS, "SAVE25") == 30.0
